window.VeilGardeData.files["Sources-VeilGardeCLI"] = {"group":"Sources-VeilGardeCLI","files":[{"path":"Sources/VeilGardeCLI/Commands/Bundle.swift","status":"added","lang":"swift","hunks":[[1,0,1,76]],"header":{"lines":[1,10],"target":"VeilGardeCLI","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1064,"scopes":[["S","BundleCommand",null,"",16,16,[16,38],76,null,-1,0,"a"],["f","directory",["_"],"static",20,20,[20,50],22,null,0,0,"a"],["S","Show",null,"",24,24,[24,33],41,null,0,0,"a"],["f","run",[],"",28,28,[28,26],40,null,2,0,"a"],["S","Verify",null,"",43,43,[43,35],53,null,0,0,"a"],["f","run",[],"",47,47,[47,26],52,null,4,0,"a"],["S","Diff",null,"",55,55,[55,33],75,null,0,0,"a"],["f","run",[],"",60,60,[60,26],74,null,6,0,"a"]],"old":"","new":"//\n//  Bundle.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde bundle`: what a detector bundle holds. `show` lists its artifacts by role with\n//        their hashes, sizes and provenance; `verify` re-hashes every file against the manifest;\n//        `diff` names the roles whose bytes differ between two bundles (the shipped one by default),\n//        which is what a promote would change.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct BundleCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"bundle\", abstract: \"Show, verify and diff detector bundles (manifest.json and its artifacts).\",\n                                                    subcommands: [Show.self, Verify.self, Diff.self])\n\n    static func directory(_ path: String?) -> URL {\n        path.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true) } ?? ShippedBundle.directory\n    }\n\n    struct Show: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"show\", abstract: \"List a bundle's artifacts and expected weights (default: the shipped bundle).\")\n        @Argument(help: \"A bundle directory.\") var path: String?\n\n        func run() throws {\n            guarded {\n                let bundle = try ModelBundle.load(BundleCommand.directory(path), verify: false)\n                print(\"bundle \\(bundle.root.path)  (\\(bundle.manifest.format))\")\n                for a in bundle.manifest.artifacts {\n                    print(\"  \" + a.slot.padding(toLength: 22, withPad: \" \", startingAt: 0) + a.file.padding(toLength: 36, withPad: \" \", startingAt: 0)\n                          + \"\\(a.sha256.prefix(12))  \\(ByteCountFormatter.string(fromByteCount: Int64(a.bytes), countStyle: .file))\" + (a.frozen ? \"  frozen\" : \"\")\n                          + (a.source.map { \"  ← \\($0)\" } ?? \"\"))\n                }\n                for w in bundle.manifest.weights { print(\"  weight \" + w.file.padding(toLength: 36, withPad: \" \", startingAt: 0) + \"\\(w.sha256.prefix(12))\") }\n                for e in bundle.manifest.history { print(\"  \\(ISO8601DateFormatter().string(from: e.date))  \\(e.kind.rawValue)  \\(e.slot)\" + (e.note.map { \"  \\($0)\" } ?? \"\")) }\n            }\n        }\n    }\n\n    struct Verify: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Re-hash every artifact of a bundle against its manifest.\")\n        @Argument(help: \"A bundle directory.\") var path: String?\n\n        func run() throws {\n            guarded {\n                let bundle = try ModelBundle.load(BundleCommand.directory(path))\n                print(\"ok  \\(bundle.manifest.artifacts.count) artifacts verified in \\(bundle.root.path)\")\n            }\n        }\n    }\n\n    struct Diff: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"diff\", abstract: \"Name the roles whose bytes differ between two bundles.\")\n        @Argument(help: \"The bundle to compare.\") var path: String\n        @Argument(help: \"The bundle to compare against (default: the shipped bundle).\") var base: String?\n\n        func run() throws {\n            guarded {\n                let a = try ModelBundle.load(BundleCommand.directory(base), verify: false).manifest\n                let b = try ModelBundle.load(BundleCommand.directory(path), verify: false).manifest\n                let slots = Set(a.artifacts.map(\\.slot)).union(b.artifacts.map(\\.slot)).sorted()\n                var changed = 0\n                for slot in slots {\n                    let x = a.artifact(slot: slot), y = b.artifact(slot: slot)\n                    guard x?.sha256 != y?.sha256 else { continue }\n                    changed += 1\n                    print(\"  \" + slot.padding(toLength: 22, withPad: \" \", startingAt: 0) + \"\\(x?.sha256.prefix(12) ?? \"absent\") → \\(y?.sha256.prefix(12) ?? \"absent\")\")\n                }\n                print(changed == 0 ? \"no artifact differs\" : \"\\(changed) role(s) differ\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Doctor.swift","status":"added","lang":"swift","hunks":[[1,0,1,29]],"header":{"lines":[1,9],"target":"VeilGardeCLI","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1072,"scopes":[["S","DoctorCommand",null,"",15,15,[15,38],29,null,-1,0,"a"],["f","run",[],"",20,20,[20,22],28,null,0,0,"a"]],"old":"","new":"//\n//  Doctor.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde doctor`: the checks before anything else. The checks live in the VeilGarde\n//        umbrella (Doctor), so every layer adds its own; a failed check says what is missing and\n//        the command exits 1.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct DoctorCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"doctor\", abstract: \"Check the setup: Metal library, work area, free space, bundle, weights.\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n\n    func run() throws {\n        print(\"veilgarde doctor\")\n        let options = workArea\n        let checks = Doctor.run(area: Result { try options.resolve() })\n        for check in checks { print(check.line) }\n        let failures = checks.filter { !$0.ok }.count\n        print(failures == 0 ? \"all checks passed\" : \"\\(failures) check(s) failed\")\n        if failures > 0 { throw ArgumentParser.ExitCode(FailureCode.doctor.rawValue) }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Features.swift","status":"added","lang":"swift","hunks":[[1,0,1,82]],"header":{"lines":[1,10],"target":"VeilGardeCLI","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1074,"scopes":[["S","FeaturesCommand",null,"",16,16,[16,40],82,null,-1,0,"a"],["S","Capture",null,"",21,21,[21,36],32,null,0,0,"a"],["f","run",[],"",26,26,[26,26],31,null,1,0,"a"],["S","Extract",null,"",34,34,[34,36],81,null,0,0,"a"],["f","run",[],"",47,47,[47,26],80,null,3,0,"a"]],"old":"","new":"//\n//  Features.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde features`: what the lens measures, without a verdict. `capture` prints the\n//        capture signature as a TSV line (peak, valid, native px, present); `extract` measures\n//        labeled images into a new store shard (the three columns every head and the fusion head\n//        train on) and keeps nothing of the images.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct FeaturesCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"features\", abstract: \"Measure images: the capture signature, and labeled images into the features-only store.\",\n        subcommands: [Capture.self, Extract.self])\n\n    struct Capture: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"capture\", abstract: \"Print the native capture signature as a TSV line: peak, valid, native px, present.\")\n\n        @Argument(help: \"The image.\") var image: String\n\n        func run() throws {\n            guarded {\n                let cs = CaptureLens.signature(try loadImage(image))\n                print(String(format: \"%.3f\\t%@\\t%d\\t%@\", cs.peak, cs.valid ? \"true\" : \"false\", cs.nativePixels, cs.present ? \"true\" : \"false\"))\n            }\n        }\n    }\n\n    struct Extract: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"extract\", abstract: \"Measure labeled images into a new feature-store shard; the images are read and dropped.\")\n        @Argument(help: \"A folder of images, a text file of paths, or a .jsonl of {path, label, category, source?, golden?, gen_family?}.\") var input: String\n        @Option(help: \"The new shard's name.\") var shard: String\n        @Option(help: \"The label for a folder or path list: 1 generated, 0 real.\") var label: Int?\n        @Option(help: \"The category for a folder or path list (art, blur, human, cgi, preview, photo, …).\") var category: String?\n        @Option(help: \"The source tag for a folder or path list.\") var source: String?\n        @Option(help: \"The feature store directory (default: <work area>/store/shards).\") var store: String?\n        @Option(help: \"Read at most this many images.\") var limit: Int?\n        @Option(help: \"small, xsmall or xxsmall.\") var dino: String = DinoVariant.small.rawValue\n        @Option(help: \"Measure only these columns, comma separated (dino_norm, dino_fusion, cap); the rest are NaN.\") var columns: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino is small, xsmall or xxsmall\") }\n                let measured = try columns.map { list in\n                    Set(try list.split(separator: \",\").map { name -> FeatureColumn in\n                        let trimmed = name.trimmingCharacters(in: .whitespaces)\n                        guard let column = FeatureColumn(rawValue: trimmed) else {\n                            throw VeilGardeFailure.usage(\"--columns names \\(FeatureColumn.allCases.map(\\.rawValue).joined(separator: \", \")), not \\(trimmed)\")\n                        }\n                        return column\n                    })\n                } ?? Set(FeatureColumn.allCases)\n                let url = datasetURL(input)\n                var items: [ExtractionItem]\n                if url.pathExtension == \"jsonl\" {\n                    items = try JSONCoding.readLines(ExtractionItem.self, from: url)\n                } else {\n                    guard let label, let category else { throw VeilGardeFailure.usage(\"a folder or a path list needs --label and --category\") }\n                    var isDirectory: ObjCBool = false\n                    FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory)\n                    let paths = isDirectory.boolValue ? ShardExtractor.images(in: url).map(\\.path)\n                        : try String(contentsOf: url, encoding: .utf8).split(separator: \"\\n\").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }\n                    items = paths.map { ExtractionItem(path: $0, label: label, category: category, source: source) }\n                }\n                if let limit { items = Array(items.prefix(limit)) }\n                let storeURL = try store.map(datasetURL) ?? workArea.resolve().root.appendingPathComponent(\"store/shards\", isDirectory: true)\n                let extractor = FeatureExtractor(variant: variant, columns: measured)\n                note(\"extract: \\(items.count) images → \\(storeURL.path)/\\(shard)\")\n                let report = try ShardExtractor.extract(items, shard: shard, store: FeatureStore(directory: storeURL), extractor: extractor, note: note)\n                print(String(format: \"%@: %d rows written, %d already in the store, %d skipped, %.1fs\", report.shard, report.rows, report.skippedKnown,\n                             report.failed.count, report.seconds))\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Flywheel.swift","status":"added","lang":"swift","hunks":[[1,0,1,293]],"header":{"lines":[1,15],"target":"VeilGardeCLI","what":[6,12],"pin":[13,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1079,"scopes":[["S","FlywheelCommand",null,"",21,21,[21,40],293,null,-1,0,"a"],["f","area",["_"],"static",27,27,[27,72],27,null,0,8,"a"],["f","battery",["_"],"static",30,30,[30,66],40,[29,29],0,0,"a"],["S","Init",null,"",42,42,[42,33],63,null,0,0,"a"],["f","run",[],"",48,48,[48,26],62,null,3,0,"a"],["S","Seed",null,"",65,65,[65,33],77,null,0,0,"a"],["f","run",[],"",70,70,[70,26],76,null,5,0,"a"],["S","Acquire",null,"",79,79,[79,36],116,null,0,0,"a"],["f","run",[],"",89,89,[89,26],115,null,7,0,"a"],["S","Gap",null,"",118,118,[118,32],139,null,0,0,"a"],["f","run",[],"",124,124,[124,26],138,null,9,0,"a"],["S","IngestImages",null,"",141,141,[141,41],156,null,0,0,"a"],["f","run",[],"",147,147,[147,26],155,null,11,0,"a"],["S","Candidates",null,"",158,158,[158,39],184,null,0,0,"a"],["f","run",[],"",165,165,[165,26],183,null,13,0,"a"],["S","AgreementCommand",null,"",186,186,[186,45],205,null,0,0,"a"],["f","run",[],"",192,192,[192,26],204,null,15,0,"a"],["S","Battery",null,"",207,207,[207,36],235,null,0,0,"a"],["f","run",[],"",216,216,[216,26],234,null,17,0,"a"],["S","Promote",null,"",237,237,[237,36],258,null,0,0,"a"],["f","run",[],"",244,244,[244,26],257,null,19,0,"a"],["S","Rollback",null,"",260,260,[260,37],273,null,0,0,"a"],["f","run",[],"",265,265,[265,26],272,null,21,0,"a"],["S","Status",null,"",275,275,[275,35],292,null,0,0,"a"],["f","run",[],"",279,279,[279,26],291,null,23,0,"a"]],"old":"","new":"//\n//  Flywheel.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde flywheel`: the regime that grows the fusion head and the specialist stack. `init` seeds the live\n//        bundle and the battery, `seed` copies a feature store in, `acquire` fetches images from the\n//        collectors into a features-only shard (no image is written), `gap` says where the base\n//        is weakest and which jobs would fill it, `ingest` measures labeled local images into a\n//        new shard, `candidates` trains the weekly candidates and writes their review,\n//        `agreement` measures the north star, `battery` gates a bundle, `promote` and `rollback`\n//        are the only writers of live/, `status` says what is live.\n//  PIN:  Battery and promote run the full detector in process, one image at a time (one MLX\n//        workload); everything else is CPU work on stored features. Exit 1 on a failed battery.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct FlywheelCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"flywheel\", abstract: \"Grow the fusion head and the specialist stack: the live bundle, the features-only store, candidates, the battery, promote and rollback.\",\n        discussion: \"Run `flywheel init` once; then ingest or seed, `candidates`, review REVIEW.md, and `promote` what passes.\",\n        subcommands: [Init.self, Seed.self, Acquire.self, Gap.self, IngestImages.self, Candidates.self, AgreementCommand.self, Battery.self, Promote.self, Rollback.self, Status.self])\n\n    static func area(_ options: WorkAreaOptions) throws -> FlywheelArea { FlywheelArea(try options.resolve()) }\n\n    /// The battery as promote and rollback run it: the full detector on a bundle, the work area's spec and floors.\n    static func battery(_ area: FlywheelArea) -> Promoter.Battery {\n        { gate, root in\n            ShippedBundle.registerWeightFolders(workArea: area.area)\n            let spec = try BatterySpec.load(area.batterySpec)\n            let report = try BatteryRunner.run(spec: spec, specURL: area.batterySpec, gate: gate, baselineURL: area.batteryBaseline,\n                                               verdicts: DetectorVerdicts(bundle: try DetectorBundle.load(root)),\n                                               vars: spec.resolvedVars(images: area.batteryImages), note: note)\n            note(report.table)\n            return report\n        }\n    }\n\n    struct Init: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"init\", abstract: \"Seed <work area>/live from the shipped bundle and <work area>/battery from the shipped spec and floors.\")\n        @Flag(help: \"Only install the shipped battery spec and floors, replacing older ones (kept under battery/retired/); live/ is left alone.\")\n        var battery = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                if battery {\n                    let r = try area.replaceBattery(spec: try FlywheelResources.batterySpec(), baseline: try FlywheelResources.batteryBaseline())\n                    print(\"battery: \\(area.batterySpec.path) (spec \\(r.batterySpecSHA256.prefix(12)), floors \\(r.batteryBaselineSHA256.prefix(12)))\")\n                    print(r.retired.map { \"retired: \\($0)\" } ?? \"retired: nothing (the shipped pair was already installed)\")\n                    return\n                }\n                let report = try area.initialize(from: try ShippedBundle.verified(), spec: try FlywheelResources.batterySpec(),\n                                                 baseline: try FlywheelResources.batteryBaseline())\n                print(\"live: \\(area.live.path) (\\(report.artifacts) artifacts)\")\n                print(\"battery: \\(area.batterySpec.path) (spec \\(report.batterySpecSHA256.prefix(12)), floors \\(report.batteryBaselineSHA256.prefix(12)))\")\n            }\n        }\n    }\n\n    struct Seed: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"seed\", abstract: \"Copy a feature store's shards into <work area>/store/shards.\")\n        @Option(help: \"The store to copy from (read only).\") var from: String\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let report = try StoreSeed.copy(from: datasetURL(from), to: area.store, note: note)\n                print(\"\\(report.copied.count) shards copied (\\(report.rows) rows, \\(report.bytes / 1_000_000) MB); \\(report.kept.count) already there\")\n            }\n        }\n    }\n\n    struct Acquire: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"acquire\", abstract: \"Fetch images from the collectors into a new features-only shard; the images are measured in memory and dropped.\")\n        @Option(help: \"The day's image budget, split across the jobs (at least 50 each).\") var budget: Int = 1000\n        @Option(help: \"Images per job, overriding the budget's split.\") var per: Int?\n        @Option(help: \"gap (the last `flywheel gap`), default, test (keyless: Wikimedia and the Met), or a targets .json.\") var targets: String = \"gap\"\n        @Option(help: \"The shard's name (default: acquire_<date>).\") var shard: String?\n        @Flag(name: .customLong(\"no-route\"), help: \"Skip the CLIP router (generated images keep their job's category, NSFW is not flagged).\") var noRoute = false\n        @Flag(name: .customLong(\"dry-run\"), help: \"List the jobs and stop.\") var dryRun = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                ShippedBundle.registerWeightFolders(workArea: area.area)\n                let shipped = try AcquireTargets.shipped()\n                let gapFile = area.root.appendingPathComponent(\"acquire/targets.json\")\n                let jobs: [AcquireJob]\n                switch targets {\n                case \"test\": jobs = shipped.testJobs\n                case \"default\": jobs = shipped.defaultJobs\n                case \"gap\":\n                    if FileManager.default.fileExists(atPath: gapFile.path) { jobs = try JSONCoding.read(GapReport.self, from: gapFile).jobs }\n                    else { note(\"acquire: no gap report yet (\\(gapFile.path)); running the default jobs\"); jobs = shipped.defaultJobs }\n                case let path: jobs = try JSONCoding.read([AcquireJob].self, from: datasetURL(path))\n                }\n                let perJob = per ?? max(50, budget / max(1, jobs.count))\n                for j in jobs { note(\"  job: \\(j.source) \\(j.category)/\\(j.label) '\\(j.query.prefix(50))'\" + (j.gap.map { \" (gap \\($0))\" } ?? \"\")) }\n                if dryRun { print(\"\\(jobs.count) jobs × \\(perJob) images\"); return }\n                let router: CategoryRouter? = noRoute ? nil : try CategoryRouter()\n                if router != nil { _ = try CLIPLens.shared.tower() }\n                let report = try Acquirer(area: area, note: note).run(jobs, perJob: perJob, extractor: FeatureExtractor(), router: router, shard: shard)\n                for j in report.jobs {\n                    print(\"\\(j.job.source) \\(j.job.category)/\\(j.job.label): \" + (j.skipped.map { \"skipped, \\($0)\" } ?? \"\\(j.accepted) kept of \\(j.fetched) fetched, rejected \\(j.rejected)\"))\n                }\n                print(report.shard.map { \"\\($0): \\(report.rows) rows in \\(area.store.path) (\\(Int(report.seconds)) s); no image was written\" } ?? \"no rows kept\")\n            }\n        }\n    }\n\n    struct Gap: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"gap\", abstract: \"Rank the store's (domain, category, label) buckets by the base's error plus its disagreement with the pooled verdict, and write the jobs that fill the worst.\")\n        @Option(help: \"Comma-separated shards to read (default: all).\") var shards: String?\n        @Flag(name: .customLong(\"no-write\"), help: \"Print the report without writing acquire/targets.json.\") var noWrite = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let report = try GapMiner.mine(try area.liveBundle(), store: FeatureStore(directory: area.store),\n                                               shards: shards.map { $0.split(separator: \",\").map(String.init) }, targets: try AcquireTargets.shipped())\n                print(report.table)\n                if !noWrite {\n                    let out = area.root.appendingPathComponent(\"acquire/targets.json\")\n                    try JSONCoding.write(report, to: out)\n                    print(\"\\nwrote \\(report.jobs.count) jobs → \\(out.path)\")\n                } else {\n                    print(\"\\n\\(report.jobs.count) jobs (not written)\")\n                }\n            }\n        }\n    }\n\n    struct IngestImages: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"ingest\", abstract: \"Measure labeled images into a new store shard (DINOv2's two views and the capture values); the images are read and dropped.\")\n        @Argument(help: \"A .jsonl of {path, label, category, source?, golden?, gen_family?}.\") var items: String\n        @Option(help: \"The new shard's name.\") var shard: String\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                let area = try FlywheelCommand.area(workArea)\n                let list = try JSONCoding.readLines(ExtractionItem.self, from: datasetURL(items))\n                let report = try Ingest.run(list, shard: shard, area: area, note: note)\n                print(String(format: \"%@: %d rows written, %d already in the store, %d skipped, %.1fs\", report.shard, report.rows, report.skippedKnown, report.failed.count, report.seconds))\n            }\n        }\n    }\n\n    struct Candidates: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"candidates\", abstract: \"Train the weekly candidates (a warm-started base and the atlas heads) on top of live, measure them, write REVIEW.md.\")\n        @Option(help: \"The candidate's id (default: weekly-<date>).\") var id: String?\n        @Flag(help: \"Replace a candidate with the same id.\") var replace = false\n        @Flag(help: \"Print the plan and stop.\") var plan = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let f = DateFormatter()\n                f.locale = Locale(identifier: \"en_US_POSIX\")\n                f.dateFormat = \"yyyyMMdd\"\n                let recipe = WeeklyCandidates.recipe(id: id ?? \"weekly-\\(f.string(from: Date()))\")\n                if plan {\n                    let p = try TrainingEngine(area: area.area, parent: area.live, store: area.store).plan(recipe)\n                    print(p.summary)\n                    return\n                }\n                let outcome = try WeeklyCandidates.run(recipe, area: area, replace: replace) { if let line = $0.line { note(line) } }\n                print(\"candidate: \\(outcome.candidate.root.path)\")\n                print(\"review:    \\(outcome.review.path)\")\n                print(String(format: \"agreement: %.4f live → %.4f candidate; AUC gap %.4f → %.4f\", outcome.liveAgreement.agreementAll,\n                             outcome.candidateAgreement.agreementAll, outcome.liveAgreement.aucGap, outcome.candidateAgreement.aucGap))\n            }\n        }\n    }\n\n    struct AgreementCommand: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"agreement\", abstract: \"Measure the north star on the store: base ↔ pooled agreement and both AUCs, for live or a bundle.\")\n        @Option(help: \"A bundle to measure instead of live (a candidate).\") var bundle: String?\n        @Flag(name: .customLong(\"no-log\"), help: \"Do not append the row to flywheel_metrics.csv.\") var noLog = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let target = try bundle.map { try ModelBundle.load(datasetURL($0)) } ?? area.liveBundle()\n                let r = try Agreement.measure(target, store: FeatureStore(directory: area.store), label: bundle.map { URL(fileURLWithPath: $0).lastPathComponent } ?? \"live\")\n                if !noLog { try Agreement.append(r, to: area.metricsCSV) }\n                print(String(format: \"%@: %d rows (camera %d, processed %d)\", r.bundle, r.rows, r.camera, r.processed))\n                print(String(format: \"  agreement %.4f all, %@ camera, %@ processed\", r.agreementAll, r.agreementCamera.map { String(format: \"%.4f\", $0) } ?? \"n/a\",\n                             r.agreementProcessed.map { String(format: \"%.4f\", $0) } ?? \"n/a\"))\n                print(String(format: \"  test %d rows: base AUC %.4f (real FPR %.3f, gen FNR %.3f); pooled AUC %.4f (real FPR %.3f, gen FNR %.3f); gap %+.4f\",\n                             r.testRows, r.baseAUC, r.baseRealFPR, r.baseGenFNR, r.weightedAUC, r.weightedRealFPR, r.weightedGenFNR, r.aucGap))\n            }\n        }\n    }\n\n    struct Battery: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"battery\", abstract: \"Run the battery on live (or a bundle): HARD groups for --gate promote, every group for full.\")\n        @Option(help: \"promote or full.\") var gate: String = BatterySpec.Gate.full.rawValue\n        @Option(help: \"A bundle to gate instead of live (a candidate).\") var bundle: String?\n        @Option(help: \"Write the report JSON here (`-` for stdout).\") var json: String?\n        @Flag(help: \"Re-record the ratchet floors from this run (full gate only, with --yes-i-reviewed).\") var rebaseline = false\n        @Flag(name: .customLong(\"yes-i-reviewed\"), help: \"Confirms a rebaseline was reviewed.\") var reviewed = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                guard let g = BatterySpec.Gate(rawValue: gate) else { throw VeilGardeFailure.usage(\"--gate is promote or full\") }\n                if rebaseline && !(g == .full && reviewed) { throw VeilGardeFailure.usage(\"--rebaseline needs --gate full and --yes-i-reviewed\") }\n                let area = try FlywheelCommand.area(workArea)\n                ShippedBundle.registerWeightFolders(workArea: area.area)\n                let root = bundle.map(datasetURL) ?? area.live\n                let spec = try BatterySpec.load(area.batterySpec)\n                let report = try BatteryRunner.run(spec: spec, specURL: area.batterySpec, gate: g, baselineURL: area.batteryBaseline,\n                                                   verdicts: DetectorVerdicts(bundle: try DetectorBundle.load(root)),\n                                                   vars: spec.resolvedVars(images: area.batteryImages), rebaseline: rebaseline, note: note)\n                let saved = area.batteryRuns.appendingPathComponent(\"\\(FlywheelArea.stamp())-\\(g.rawValue).json\")\n                try JSONCoding.write(report, to: saved)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(report.table)\n                note(\"report: \\(saved.path)\")\n                if !report.pass { throw ExitCode(1) }\n            }\n        }\n    }\n\n    struct Promote: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"promote\", abstract: \"Promote one slot from a candidate into live, behind its battery; a failure restores live.\")\n        @Argument(help: \"base, combiner, or a head (art, blur, human, cgi, preview, art-pair, screenshot, semtile).\") var slot: String\n        @Option(help: \"The candidate bundle.\") var from: String\n        @Flag(name: .customLong(\"dry-run\"), help: \"Run every check and print what would change; write nothing, run no battery.\") var dryRun = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let s = try FlywheelSlot(parsing: slot)\n                let promoter = Promoter(area: area, battery: FlywheelCommand.battery(area), note: note)\n                if dryRun {\n                    let preview = try promoter.preview(s, from: datasetURL(from), store: FeatureStore(directory: area.store))\n                    print(\"would promote \" + preview.summary)\n                    return\n                }\n                let record = try promoter.promote(s, from: datasetURL(from), store: FeatureStore(directory: area.store))\n                print(\"promoted \\(record.slot): \\(record.fromSHA256?.prefix(12) ?? \"none\") → \\(record.toSHA256?.prefix(12) ?? \"?\") (battery PASS, snapshot \\(record.snapshot ?? \"?\"))\")\n            }\n        }\n    }\n\n    struct Rollback: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"rollback\", abstract: \"Restore live from a snapshot in live/.history (the newest by default), then run the full battery.\")\n        @Argument(help: \"The snapshot's stamp.\") var stamp: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let record = try Promoter(area: area, battery: FlywheelCommand.battery(area), note: note).rollback(to: stamp)\n                print(\"rolled back to \\(record.snapshot ?? \"?\") (battery \\(record.battery ?? \"?\"))\")\n                if record.battery != \"PASS\" { throw ExitCode(1) }\n            }\n        }\n    }\n\n    struct Status: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"status\", abstract: \"What is live, what moved last, and the snapshots to roll back to.\")\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let live = try area.liveBundle()\n                print(\"live: \\(live.root.path)\")\n                for a in live.manifest.artifacts { print(\"  \\(a.slot.padding(toLength: 22, withPad: \" \", startingAt: 0)) \\(a.sha256.prefix(12))  \\(a.frozen ? \"frozen \" : \"       \")\\(a.file)\") }\n                for e in live.manifest.history.suffix(5) { print(\"  \\(e.kind.rawValue) \\(e.slot) \\(e.date)\") }\n                let snapshots = Promoter(area: area, battery: { _, _ in throw VeilGardeFailure.internalError(\"status runs no battery\") }).snapshots()\n                print(\"snapshots: \\(snapshots.isEmpty ? \"none\" : snapshots.suffix(5).joined(separator: \", \"))\")\n                let shards = FeatureStore(directory: area.store).shardNames()\n                print(\"store: \\(shards.count) shards in \\(area.store.path)\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Parity.swift","status":"added","lang":"swift","hunks":[[1,0,1,100]],"header":{"lines":[1,11],"target":"VeilGardeCLI","what":[6,9],"pin":[10,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":1104,"scopes":[["S","ParityCommand",null,"",17,17,[17,38],100,null,-1,0,"a"],["f","floats",["_"],"static",22,22,[22,48],22,null,0,8,"a"],["f","report",["_","pass"],"static",24,24,[24,70],27,null,0,0,"a"],["S","Dino",null,"",29,29,[29,33],68,null,0,0,"a"],["f","run",[],"",36,36,[36,26],67,null,3,0,"a"],["f","cosine",["_","_"],"",42,42,[42,65],46,null,4,4,"a"],["S","Clip",null,"",70,70,[70,33],99,null,0,0,"a"],["f","run",[],"",75,75,[75,26],98,null,6,0,"a"],["f","cosine",["_","_"],"",83,83,[83,85],83,null,7,12,"a"]],"old":"","new":"//\n//  Parity.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde parity`: the checks against the Python references. `dino` compares DINOv2\n//        embeddings of HF-preprocessed pixels with the dino_parity_dump.py references, isolating the\n//        ViT; with --images it runs the full Swift preprocessing on the raw images too (the end-to-end\n//        check). `clip` does the same for CLIP's vision tower.\n//  PIN:  The thresholds: ViT cosine ≥ 0.999; end to end ≥ 0.99.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct ParityCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"parity\", abstract: \"Check the DINOv2 and CLIP towers against the Python fixtures.\",\n        subcommands: [Dino.self, Clip.self])\n\n    static func floats(_ any: Any?) -> [Float]? { (any as? [Any])?.map { Float(($0 as? NSNumber)?.doubleValue ?? 0) } }\n\n    static func report(_ values: [String: Double], pass: Bool) throws {\n        try emitJSON(try JSONSerialization.data(withJSONObject: values, options: [.sortedKeys]), to: \"-\")\n        if !pass { throw ArgumentParser.ExitCode(FailureCode.parityMismatch.rawValue) }\n    }\n\n    struct Dino: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"dino\", abstract: \"Compare DINOv2 embeddings with the dino_parity_dump.py references (<name>.pixels, <name>.emb).\")\n\n        @Argument(help: \"The fixture safetensors.\") var fixture: String\n        @Option(help: \"The raw images' folder, for the end-to-end check (bahamut.jpg, test1.png, IMG_4096.jpeg).\") var images: String?\n        @Option(help: \"DINOv2 weights: small, xsmall or xxsmall.\") var dino: String = DinoVariant.small.rawValue\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino must be small, xsmall or xxsmall\") }\n                let file = try SafetensorsFile(url: URL(fileURLWithPath: (fixture as NSString).expandingTildeInPath))\n                let bases = Set(file.names.filter { $0.hasSuffix(\".pixels\") }.map { String($0.dropLast(\".pixels\".count)) }).sorted()\n                func cosine(_ a: [Float], _ b: [Float]) -> Float {\n                    var dot: Float = 0, na: Float = 0, nb: Float = 0\n                    for i in 0..<min(a.count, b.count) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i] }\n                    return dot / (na.squareRoot() * nb.squareRoot())\n                }\n                var allPass = true\n                for base in bases {\n                    let pixels = try file.float32(\"\\(base).pixels\"), reference = try file.float32(\"\\(base).emb\")\n                    let cos = cosine(try SemanticLens.embedding(pixels: pixels, variant: variant), reference)\n                    let pass = cos >= 0.999\n                    allPass = allPass && pass\n                    print(base.padding(toLength: 12, withPad: \" \", startingAt: 0) + String(format: \" vit cosine %.5f  \", cos) + (pass ? \"PASS\" : \"FAIL\"))\n                }\n                if let images {\n                    for (base, name) in [(\"bahamut\", \"bahamut.jpg\"), (\"test1\", \"test1.png\"), (\"IMG_4096\", \"IMG_4096.jpeg\")] {\n                        let url = URL(fileURLWithPath: (images as NSString).expandingTildeInPath).appendingPathComponent(name)\n                        guard let reference = try? file.float32(\"\\(base).emb\"), let cg = try? ImageDecoding.cgImage(contentsOf: url) else { print(\"\\(base): missing\"); continue }\n                        let cos = cosine(try SemanticLens.fusionEmbedding(cg, variant: variant), reference)\n                        let pass = cos >= 0.99\n                        allPass = allPass && pass\n                        print(base.padding(toLength: 12, withPad: \" \", startingAt: 0) + String(format: \" e2e cosine %.5f  \", cos) + (pass ? \"PASS\" : \"FAIL\"))\n                    }\n                }\n                if !allPass { throw ArgumentParser.ExitCode(FailureCode.parityMismatch.rawValue) }\n            }\n        }\n    }\n\n    struct Clip: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"clip\", abstract: \"The CLIP vision tower against Hugging Face's embeddings on the same pixels (clip_parity.safetensors).\")\n        @Argument(help: \"The fixture (default: Tests/VeilGardeLensTests/Fixtures/clip_parity.safetensors).\") var fixture: String?\n        @Option(help: \"The image files the fixture's first rows came from, to also check the Swift preprocessing end to end.\") var images: [String] = []\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                let url = fixture.map(datasetURL) ?? URL(fileURLWithPath: \"Tests/VeilGardeLensTests/Fixtures/clip_parity.safetensors\")\n                let f = try SafetensorsFile(url: url)\n                let pixels = try f.uint8(\"pixels\"), expected = try f.float32(\"embeds\")\n                let n = try f.tensor(\"pixels\").shape[0]\n                let ours = try CLIPLens.shared.tower()(CLIPPreprocess.input(pixels: pixels, count: n)).asArray(Float.self)\n                func cosine(_ a: ArraySlice<Float>, _ b: ArraySlice<Float>) -> Float { zip(a, b).reduce(Float(0)) { $0 + $1.0 * $1.1 } }\n                var worst: Float = 1\n                for i in 0..<n {\n                    let c = cosine(ours[(i * 512)..<((i + 1) * 512)], expected[(i * 512)..<((i + 1) * 512)])\n                    worst = min(worst, c)\n                    print(String(format: \"image %d: cosine %.7f (same pixels)\", i, c))\n                }\n                for (i, path) in images.enumerated() where i < n {\n                    let e = try CLIPLens.embedding(try loadImage(path))\n                    print(String(format: \"%@: cosine %.5f (decoded and preprocessed here, HF's PIL resize there)\", (path as NSString).lastPathComponent,\n                                 cosine(e[0..<512], expected[(i * 512)..<((i + 1) * 512)])))\n                }\n                print(String(format: \"worst cosine on the same pixels: %.7f %@\", worst, worst >= 0.999 ? \"(≥ 0.999)\" : \"(below 0.999)\"))\n                if worst < 0.999 { throw ExitCode(1) }\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Research.swift","status":"added","lang":"swift","hunks":[[1,0,1,196]],"header":{"lines":[1,15],"target":"VeilGardeCLI","what":[6,10],"pin":[11,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1113,"scopes":[["S","ResearchCommand",null,"",21,21,[21,40],99,null,-1,0,"a"],["f","output",["_","_"],"static",26,26,[26,71],30,null,0,0,"a"],["S","Census",null,"",32,32,[32,35],98,null,0,0,"a"],["f","run",[],"",45,45,[45,26],97,null,2,0,"a"],["S","MechanismCensus",null,"",102,102,[102,32],196,[101,101],-1,0,"a"],["S","Row",null,"",103,103,[103,24],121,null,4,0,"a"],["f","add",["_","label","_","domain"],"mutating",148,148,[148,92],169,null,4,0,"a"],["f","counted",["_","_","_"],"static",171,171,[171,119],175,null,4,0,"a"],["v","table",null,"",177,177,[177,22],195,null,4,0,"a"]],"old":"","new":"//\n//  Research.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research`: measurements of the detector, part by part. `census` runs the full\n//        detector over images (the battery's, a final_mixed sample, or any given) and counts how\n//        often each mechanism and stack row runs, how often it decides the call, and how often the\n//        stack and the semantic chain move it; `compare` judges one census against another\n//        (ResearchCompare.swift).\n//  PIN:  census is one MLX workload, one image at a time. It writes\n//        <work area>/research/census-<stamp>.json and prints a table, and names the bundle it ran\n//        and its hashes. A census written before 2026-10-21 also carries the warp lens's and the\n//        camera-sensor's fields; they read as absent now.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct ResearchCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"research\", abstract: \"Measure the detector part by part: the mechanism census, and one census judged against another.\",\n        subcommands: [Census.self, Compare.self])\n\n    static func output(_ area: WorkArea, _ what: String) throws -> URL {\n        let folder = area.root.appendingPathComponent(\"research\", isDirectory: true)\n        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)\n        return folder.appendingPathComponent(\"\\(what)-\\(FlywheelArea.stamp()).json\")\n    }\n\n    struct Census: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"census\", abstract: \"Run the full detector over images and count how often each mechanism runs and decides the call.\",\n            discussion: \"With no images it takes the battery's (every group) and a final_mixed sample. One MLX workload, one image at a time.\")\n        @Argument(help: \"Images, folders (searched recursively), or text files of image paths (one per line).\") var images: [String] = []\n        @Option(help: \"The label of the images named as arguments: real or generated.\") var label: String?\n        @Flag(help: \"Add the battery's images (every group of the work area's spec).\") var battery = false\n        @Option(help: \"Add this many final_mixed images, half real and half generated, every k-th by name.\") var sample = 0\n        @Option(name: .customLong(\"final-mixed\"), help: \"The final_mixed folder (default: final_mixed under VEILGARDE_DATASETS, else the work area's datasets/).\") var finalMixed: String?\n        @Option(help: \"Write the census here too (`-` for stdout).\") var json: String?\n        @OptionGroup var route: RouteOptions\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                if let label, ![\"real\", \"generated\"].contains(label) { throw VeilGardeFailure.usage(\"--label is real or generated, not \\(label)\") }\n                var items: [(path: String, label: String?)] = []\n                for input in images { items += try imageInputs(input).map { ($0.path, label) } }\n                let defaults = images.isEmpty && !battery && sample == 0\n                if battery || defaults {\n                    let fly = FlywheelArea(area)\n                    let spec = try BatterySpec.load(fly.batterySpec)\n                    for group in try spec.resolve(gate: .full, vars: spec.resolvedVars(images: fly.batteryImages)) {\n                        items += group.files.map { ($0, group.want) }\n                    }\n                }\n                let count = defaults ? 200 : sample\n                if count > 0 {\n                    guard let finalMixed = finalMixed.map(datasetURL) ?? WorkArea.datasets().map({ $0.appendingPathComponent(\"final_mixed\") }) else {\n                        throw VeilGardeFailure.usage(\"no final_mixed: pass --final-mixed or set VEILGARDE_DATASETS\")\n                    }\n                    for label in [\"real\", \"generated\"] {\n                        let folder = finalMixed.appendingPathComponent(label)\n                        let names = ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])\n                            .filter { !$0.hasPrefix(\".\") && [\"jpg\", \"jpeg\", \"png\", \"webp\", \"heic\"].contains(URL(fileURLWithPath: $0).pathExtension.lowercased()) }.sorted()\n                        let k = max(1, names.count / max(1, count / 2))\n                        items += stride(from: 0, to: names.count, by: k).prefix(count / 2).map { (folder.appendingPathComponent(names[$0]).path, label) }\n                    }\n                }\n                guard !items.isEmpty else { throw VeilGardeFailure.usage(\"no images: name some, or pass --battery or --sample\") }\n                let config = try route.config()\n                var census = MechanismCensus()\n                census.bundle = config.bundle.directory.path\n                census.provenance = config.bundle.provenance\n                census.weightsDir = route.weightsDir\n                census.dinoVariant = config.dinoVariant.rawValue\n                census.coreVersion = VeilGardeVersion.string\n                for (k, item) in items.enumerated() {\n                    defer { LensRuntime.releaseMemory() }\n                    do {\n                        let cg = try loadImage(item.path)\n                        let routed = try Detector.shared.detect(cgImage: cg, config: config)\n                        census.add(item.path, label: item.label, routed.result, domain: routed.domain.rawValue)\n                    } catch {\n                        census.errors.append(\"\\(item.path): \\(error)\")\n                    }\n                    if (k + 1) % 25 == 0 { note(\"census: \\(k + 1) of \\(items.count) images\") }\n                }\n                let file = try ResearchCommand.output(area, \"census\")\n                try JSONCoding.write(census, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(census), to: json) }\n                print(census.table)\n                note(\"census: \\(file.path)\")\n            }\n        }\n    }\n}\n\n/// How often each part of the router ran on a set of images, and how often it decided.\nstruct MechanismCensus: Codable {\n    struct Row: Codable {\n        var path: String\n        var label: String?\n        var route: String\n        var capture: String\n        var baseP: Float?\n        var preSemanticP: Float?\n        var p: Float\n        var call: String\n        var preSemanticCall: String?\n        var shown: [String]\n        var decisive: [String]\n        var semanticTriggered: Bool\n        var semanticDecisive: Bool\n        var previewTriggered: Bool\n        var previewDecisive: Bool\n        /// The base expert's own call (the first stack row).\n        var baseCall: String? = nil\n    }\n\n    var date = Date()\n    /// What ran: the bundle, its artifacts' hashes, and the weights.\n    var bundle: String? = nil\n    var provenance: [String: String]? = nil\n    var weightsDir: String? = nil\n    var dinoVariant: String? = nil\n    var coreVersion: String? = nil\n    var rows: [Row] = []\n    var errors: [String] = []\n    var routes: [String: Int] = [:]\n    var capture: [String: Int] = [:]\n    /// Stack rows by name: how many images showed each.\n    var shown: [String: Int] = [:]\n    /// Stack rows at full weight (the part that decided or moved the call), by name, then by label.\n    var decisive: [String: [String: Int]] = [:]\n    /// Capture-absent images whose pre-semantic call differs from the fusion base's call at 0.5.\n    var stackMovedCall = 0\n    /// Images whose final call differs from the pre-semantic one.\n    var semanticMovedCall = 0\n    /// The final call against the label, where the label is known.\n    var correct: [String: Int] = [:]\n    var labelled: [String: Int] = [:]\n    /// By label (\"unlabelled\" when unknown), then the routed call.\n    var finalCalls: [String: [String: Int]]? = nil\n\n    mutating func add(_ path: String, label: String?, _ r: InferenceResult, domain: String) {\n        let cap = r.captureSignature.map { $0.valid ? ($0.present ? \"present\" : \"absent\") : \"invalid\" } ?? \"none\"\n        let d = r.routeDiagnostics\n        let stack = r.specialists ?? []\n        var row = Row(path: path, label: label, route: domain, capture: cap, baseP: d?.baseP, preSemanticP: d?.preSemanticP, p: r.p,\n                      call: r.prediction, preSemanticCall: d?.preSemanticPrediction, shown: stack.map(\\.name),\n                      decisive: stack.filter { $0.weight >= 1 }.map(\\.name), semanticTriggered: d?.semanticTriggered ?? false,\n                      semanticDecisive: d?.semanticDecisive ?? false, previewTriggered: d?.previewTriggered ?? false, previewDecisive: d?.previewDecisive ?? false)\n        row.baseCall = stack.first?.verdict\n        rows.append(row)\n        finalCalls = Self.counted(finalCalls, label ?? \"unlabelled\", row.call)\n        routes[domain, default: 0] += 1\n        capture[cap, default: 0] += 1\n        for name in Set(row.shown) { shown[name, default: 0] += 1 }\n        for name in Set(row.decisive) { decisive[name, default: [:]][label ?? \"unlabelled\", default: 0] += 1 }\n        if cap != \"present\", let base = d?.baseP, let pre = d?.preSemanticPrediction, (base > 0.5 ? \"generated\" : \"real\") != pre { stackMovedCall += 1 }\n        if let pre = d?.preSemanticPrediction, pre != r.prediction { semanticMovedCall += 1 }\n        if let label {\n            labelled[label, default: 0] += 1\n            if r.prediction == label { correct[label, default: 0] += 1 }\n        }\n    }\n\n    static func counted(_ table: [String: [String: Int]]?, _ label: String, _ call: String) -> [String: [String: Int]] {\n        var t = table ?? [:]\n        t[label, default: [:]][call, default: 0] += 1\n        return t\n    }\n\n    var table: String {\n        var lines = [\"census: \\(rows.count) images (\\(errors.count) errors); routes \" + routes.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")\n                     + \"; capture \" + capture.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")]\n        if let bundle { lines.append(\"bundle \\(bundle)\") }\n        lines.append(\"  stack row                shown  full weight (by label)\")\n        for (name, n) in shown.sorted(by: { $0.value > $1.value }) {\n            let by = (decisive[name] ?? [:]).sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")\n            let label = name.count >= 24 ? name : name + String(repeating: \" \", count: 24 - name.count)\n            lines.append(\"  \" + label + String(format: \" %5d  \", n) + (by.isEmpty ? \"—\" : by))\n        }\n        lines.append(\"the stack moved the base's call on \\(stackMovedCall) capture-absent images; the semantic chain moved the call on \\(semanticMovedCall)\")\n        lines.append(\"correct: \" + labelled.sorted { $0.key < $1.key }.map { \"\\($0.key) \\(correct[$0.key] ?? 0) of \\($0.value)\" }.joined(separator: \", \"))\n        if let table = finalCalls {\n            lines.append(\"routed calls: \" + table.sorted { $0.key < $1.key }.map { label, calls in\n                \"\\(label) \" + [\"real\", \"inconclusive\", \"generated\"].map { \"\\($0) \\(calls[$0] ?? 0)\" }.joined(separator: \" / \")\n            }.joined(separator: \"; \"))\n        }\n        return lines.joined(separator: \"\\n\")\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/ResearchCompare.swift","status":"added","lang":"swift","hunks":[[1,0,1,166]],"header":{"lines":[1,14],"target":"VeilGardeCLI","what":[6,9],"pin":[10,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":1122,"scopes":[["S","DetectorComparisonRules",null,"",22,22,[22,40],32,[20,21],-1,0,"a"],["v","text",null,"",25,25,[25,23],31,null,0,0,"a"],["S","CompareSide",null,"",34,34,[34,28],46,null,-1,0,"a"],["S","CompareReport",null,"",48,48,[48,30],66,null,-1,0,"a"],["X","ResearchCommand",null,"",68,68,[68,26],166,null,-1,0,"a"],["S","Compare",null,"",69,69,[69,36],165,null,4,0,"a"],["f","run",[],"",83,83,[83,26],95,null,5,0,"a"],["f","load",["_"],"static",97,97,[97,67],97,null,5,8,"a"],["f","side",["_","path","iphone","iphonePath"],"static",99,99,[99,128],110,null,5,0,"a"],["f","share",["_"],"",105,105,[105,44],105,null,8,12,"a"],["f","compare",["name","judge","reference","variant","referenceIPhone","variantIPhone","battery","rules"],"static",112,112,[113,102],149,null,5,0,"a"],["f","table",["_"],"static",151,151,[151,56],164,null,5,0,"a"],["f","fm",["_"],"",152,152,[152,48],156,null,11,4,"a"]],"old":"","new":"//\n//  ResearchCompare.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research compare`: one detector judged against another from their censuses,\n//        image by image: correct calls by label, the calls the variant moved to the right label and\n//        to the wrong one, the iPhone originals' routed real share, and the battery's verdict, read\n//        against rules fixed before any comparison runs (DetectorComparisonRules).\n//  PIN:  Reads only the JSONs `research census` and `flywheel battery` wrote, joined by image path.\n//        The labelled images R2 counts are the census rows under a final_mixed folder (200 in the\n//        default census); the iPhone originals are the second census of each side. A census written\n//        before 2026-10-21 reads as is. Writes <work area>/research/compare-<name>-<stamp>.json.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\n/// The comparison's rules, fixed before any comparison runs (ledger decision-99, the sensor and warp\n/// rules retired on 2026-10-21).\nstruct DetectorComparisonRules: Codable {\n    var maxCorrectLoss = 2\n\n    var text: [String] {\n        [\n            \"R1. The full battery decides PASS or FAIL with its recorded floors.\",\n            \"R2. A part is not necessary only when the battery passes without it, the labelled final_mixed census images lose at most \\(maxCorrectLoss) correct calls against the detector with the part (inconclusive counts as wrong), and the changed calls moved to the wrong label are no more than those moved to the right one.\",\n            \"R3. Every comparison is reported whatever another one found; the store's images, final_mixed's among them, trained the shipped models.\",\n        ]\n    }\n}\n\nstruct CompareSide: Codable {\n    var census: String\n    var iphone: String?\n    var provenance: [String: String]?\n    /// Labelled final_mixed images called right, by label, and their total.\n    var finalMixedCorrect: [String: Int]\n    var finalMixedImages: Int\n    /// Every labelled census image called right, and their total.\n    var labelledCorrect: Int\n    var labelledImages: Int\n    var iphoneImages: Int?\n    var iphoneRoutedReal: Double?\n}\n\nstruct CompareReport: Codable {\n    var date: Date\n    var name: String\n    var judge: String\n    var rules: [String]\n    var reference: CompareSide\n    var variant: CompareSide\n    var joined: Int\n    var unmatched: Int\n    /// Labelled images whose routed call moved, and where it moved.\n    var moved: Int\n    var movedToRight: Int\n    var movedToWrong: Int\n    var battery: String?\n    var batteryPass: Bool?\n    var batteryStatuses: [String: String]?\n    var verdict: String\n    var reasons: [String]\n}\n\nextension ResearchCommand {\n    struct Compare: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"compare\", abstract: \"Judge a detector variant against a reference from their censuses and battery report.\",\n            discussion: \"--judge part applies R2 (is the part taken out necessary); --judge none only measures.\")\n        @Option(help: \"The reference's census JSON.\") var reference: String\n        @Option(help: \"The variant's census JSON.\") var variant: String\n        @Option(name: .customLong(\"reference-iphone\"), help: \"The reference's census of the iPhone originals.\") var referenceIPhone: String?\n        @Option(name: .customLong(\"variant-iphone\"), help: \"The variant's census of the iPhone originals.\") var variantIPhone: String?\n        @Option(help: \"The variant's battery report JSON.\") var battery: String?\n        @Option(help: \"part or none.\") var judge: String = \"none\"\n        @Option(help: \"A name for the variant in the report.\") var name: String = \"variant\"\n        @Option(help: \"Write the report here too (`-` for stdout).\") var json: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                guard [\"part\", \"none\"].contains(judge) else { throw VeilGardeFailure.usage(\"--judge is part or none, not \\(judge)\") }\n                let area = try workArea.resolve()\n                let report = try Self.compare(name: name, judge: judge, reference: reference, variant: variant, referenceIPhone: referenceIPhone,\n                                              variantIPhone: variantIPhone, battery: battery, rules: DetectorComparisonRules())\n                let file = try ResearchCommand.output(area, \"compare-\\(name)\")\n                try JSONCoding.write(report, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(Self.table(report))\n                note(\"report: \\(file.path)\")\n            }\n        }\n\n        static func load(_ path: String) throws -> MechanismCensus { try JSONCoding.read(MechanismCensus.self, from: datasetURL(path)) }\n\n        static func side(_ census: MechanismCensus, path: String, iphone: MechanismCensus?, iphonePath: String?) -> CompareSide {\n            let labelled = census.rows.filter { $0.label != nil }\n            let finalMixed = labelled.filter { $0.path.contains(\"/final_mixed/\") }\n            var byLabel: [String: Int] = [:]\n            for row in finalMixed where row.call == row.label { byLabel[row.label!, default: 0] += 1 }\n            let iphoneRows = iphone?.rows ?? []\n            func share(_ n: Int) -> Double? { iphoneRows.isEmpty ? nil : Double(n) / Double(iphoneRows.count) }\n            return CompareSide(census: datasetURL(path).path, iphone: iphonePath.map { datasetURL($0).path }, provenance: census.provenance,\n                               finalMixedCorrect: byLabel, finalMixedImages: finalMixed.count, labelledCorrect: labelled.filter { $0.call == $0.label }.count,\n                               labelledImages: labelled.count, iphoneImages: iphone.map { _ in iphoneRows.count },\n                               iphoneRoutedReal: share(iphoneRows.filter { $0.call == \"real\" }.count))\n        }\n\n        static func compare(name: String, judge: String, reference: String, variant: String, referenceIPhone: String?, variantIPhone: String?,\n                            battery: String?, rules: DetectorComparisonRules) throws -> CompareReport {\n            let ref = try load(reference), v = try load(variant)\n            let refI = try referenceIPhone.map(load), vI = try variantIPhone.map(load)\n            let a = side(ref, path: reference, iphone: refI, iphonePath: referenceIPhone)\n            let b = side(v, path: variant, iphone: vI, iphonePath: variantIPhone)\n            let byPath = Dictionary(v.rows.map { ($0.path, $0) }, uniquingKeysWith: { first, _ in first })\n            var joined = 0, unmatched = 0, moved = 0, right = 0, wrong = 0\n            for row in ref.rows {\n                guard let other = byPath[row.path] else { unmatched += 1; continue }\n                joined += 1\n                guard let label = row.label, row.call != other.call else { continue }\n                moved += 1\n                if other.call == label { right += 1 } else { wrong += 1 }\n            }\n            var pass: Bool? = nil, statuses: [String: String]? = nil\n            if let battery {\n                let object = try JSONSerialization.jsonObject(with: Data(contentsOf: datasetURL(battery))) as? [String: Any]\n                pass = object?[\"pass\"] as? Bool\n                // The battery report lists its statuses as [{group, status, floor}].\n                if let list = object?[\"statuses\"] as? [[String: Any]] {\n                    statuses = Dictionary(list.compactMap { s in (s[\"group\"] as? String).map { ($0, \"\\(s[\"status\"] ?? \"\")\") } }, uniquingKeysWith: { first, _ in first })\n                }\n            }\n            let loss = a.finalMixedCorrect.values.reduce(0, +) - b.finalMixedCorrect.values.reduce(0, +)\n            var reasons: [String] = []\n            var verdict = \"measured\"\n            switch judge {\n            case \"part\":\n                if pass != true { reasons.append(\"the battery does not pass without it (\\(pass.map { $0 ? \"PASS\" : \"FAIL\" } ?? \"no report\"))\") }\n                if loss > rules.maxCorrectLoss { reasons.append(\"the labelled final_mixed images lose \\(loss) correct calls (bar \\(rules.maxCorrectLoss))\") }\n                if wrong > right { reasons.append(\"\\(wrong) calls moved to the wrong label against \\(right) to the right one\") }\n                verdict = reasons.isEmpty ? \"not necessary (R2)\" : \"necessary (R2)\"\n            default: break\n            }\n            return CompareReport(date: Date(), name: name, judge: judge, rules: rules.text, reference: a, variant: b, joined: joined, unmatched: unmatched,\n                                 moved: moved, movedToRight: right, movedToWrong: wrong, battery: battery.map { datasetURL($0).path }, batteryPass: pass, batteryStatuses: statuses, verdict: verdict, reasons: reasons)\n        }\n\n        static func table(_ r: CompareReport) -> String {\n            func fm(_ s: CompareSide) -> String {\n                \"final_mixed correct \\(s.finalMixedCorrect.values.reduce(0, +)) of \\(s.finalMixedImages) (\" + s.finalMixedCorrect.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \") + \")\"\n                    + \"; labelled \\(s.labelledCorrect) of \\(s.labelledImages)\"\n                    + (s.iphoneImages.map { n in String(format: \"; iPhone %d: routed real %.3f\", n, s.iphoneRoutedReal ?? .nan) } ?? \"\")\n            }\n            var lines = [\"\\(r.name) (\\(r.judge)): \\(r.verdict)\"]\n            lines.append(\"  reference: \" + fm(r.reference))\n            lines.append(\"  variant:   \" + fm(r.variant))\n            lines.append(\"  \\(r.joined) images joined (\\(r.unmatched) unmatched); \\(r.moved) labelled calls moved, \\(r.movedToRight) to the right label, \\(r.movedToWrong) to the wrong one\")\n            if let pass = r.batteryPass { lines.append(\"  battery: \\(pass ? \"PASS\" : \"FAIL\")\" + (r.batteryStatuses.map { \" \" + $0.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \") } ?? \"\")) }\n            for reason in r.reasons { lines.append(\"  - \" + reason) }\n            return lines.joined(separator: \"\\n\")\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Route.swift","status":"added","lang":"swift","hunks":[[1,0,1,88]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,10],"pin":[11,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1135,"scopes":[["S","RouteCommand",null,"",18,18,[18,37],44,null,-1,0,"a"],["f","run",[],"",27,27,[27,22],43,null,0,0,"a"],["S","BatchCommand",null,"",46,46,[46,37],88,null,-1,0,"a"],["f","run",[],"",53,53,[53,22],87,null,2,0,"a"]],"old":"","new":"//\n//  Route.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde route <image>`: the full detector. The router picks the domain, the base expert\n//        runs (camera: the fusion head; screenshot: the content head), and the specialists, the\n//        frame seam and the semantic chain compound on it. Prints the domain, the verdict, the\n//        base expert's own P(AI), the capture signature and the specialist stack, or the schema-v3\n//        JSON with --json. `batch` routes a manifest of images into a JSONL of results.\n//  PIN:  --json writes times_sec [], device \"route\", route = the domain.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct RouteCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"route\", abstract: \"Run the full detector: route, base expert, specialist stack, mechanisms.\")\n\n    @Argument(help: \"The image.\") var image: String\n    @OptionGroup var route: RouteOptions\n    @Option(help: \"Skip domain detection: camera or screenshot.\") var hint: String?\n    @Flag(help: \"The schema-v3 JSON on stdout.\") var json = false\n    @Flag(help: \"Run MLX on the CPU.\") var cpu = false\n\n    func run() throws {\n        guarded {\n            let config = try route.config()\n            let domainHint = try parseHint(hint)\n            let cg = try loadImage(image)\n            let routed = try LensRuntime.withDevice(cpu: cpu) { try Detector.shared.detect(cgImage: cg, config: config, hint: domainHint) }\n            let r = routed.result\n            if json {\n                try emitJSON(try ResultJSON.encode(r, times: [], device: \"route\", route: routed.domain.rawValue), to: \"-\")\n                return\n            }\n            let capture = r.captureSignature.map { !$0.valid ? \"invalid\" : ($0.present ? \"present\" : \"absent\") } ?? \"n/a\"\n            let stack = (r.specialists ?? []).map { String(format: \"%@(p=%.2f w=%.1f→%@)\", $0.name, $0.pAI, $0.weight, $0.verdict) }.joined(separator: \" + \")\n            print(String(format: \"route  domain=%@  verdict=%@  p=%.4f  base=%@ %.4f  capture=%@\\n  stack: %@\",\n                         routed.domain.rawValue, r.prediction, r.p, r.scorer, r.routeDiagnostics?.baseP ?? r.p, capture, stack))\n        }\n    }\n}\n\nstruct BatchCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"batch\", abstract: \"Route a JSONL manifest of {id, path, hint} rows, in order, into a JSONL of results.\")\n\n    @Argument(help: \"The manifest: one {\\\"id\\\", \\\"path\\\", \\\"hint\\\"} object per line.\") var input: String\n    @Argument(help: \"The output JSONL; it must not exist.\") var output: String\n    @OptionGroup var route: RouteOptions\n\n    func run() throws {\n        guarded {\n            let inputURL = URL(fileURLWithPath: (input as NSString).expandingTildeInPath).standardizedFileURL\n            let outputURL = URL(fileURLWithPath: (output as NSString).expandingTildeInPath).standardizedFileURL\n            guard inputURL.resolvingSymlinksInPath() != outputURL.resolvingSymlinksInPath() else { throw VeilGardeFailure.usage(\"the input and output paths must differ\") }\n            guard !FileManager.default.fileExists(atPath: outputURL.path) else { throw VeilGardeFailure.exists(\"refusing to overwrite \\(outputURL.path)\") }\n            let config = try route.config()\n            // The whole manifest validates before any inference.\n            let items = try RouteBatch.parse(Data(contentsOf: inputURL))\n            let temporary = outputURL.deletingLastPathComponent().appendingPathComponent(\".\\(outputURL.lastPathComponent).tmp-\\(UUID().uuidString)\")\n            guard FileManager.default.createFile(atPath: temporary.path, contents: nil) else { throw VeilGardeFailure.internalError(\"cannot create \\(temporary.path)\") }\n            do {\n                let handle = try FileHandle(forWritingTo: temporary)\n                for (index, item) in items.enumerated() {\n                    defer { LensRuntime.releaseMemory() }\n                    let cg = try loadImage(item.path)\n                    let routed = try Detector.shared.detect(cgImage: cg, config: config, hint: item.hint)\n                    var line = Data(\"{\\\"id\\\":\".utf8)\n                    line.append(try JSONEncoder().encode(item.id))\n                    line.append(Data(\",\\\"result\\\":\".utf8))\n                    line.append(try ResultJSON.encode(routed.result, times: [], device: \"route-batch\", route: routed.domain.rawValue))\n                    line.append(Data(\"}\\n\".utf8))\n                    try handle.write(contentsOf: line)\n                    if (index + 1).isMultiple(of: 64) { try handle.synchronize(); note(\"batch: \\(index + 1)/\\(items.count)\") }\n                }\n                try handle.synchronize()\n                try handle.close()\n                try FileManager.default.moveItem(at: temporary, to: outputURL)\n                note(\"batch: \\(items.count) results → \\(outputURL.path)\")\n            } catch {\n                try? FileManager.default.removeItem(at: temporary)\n                throw error\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Train.swift","status":"added","lang":"swift","hunks":[[1,0,1,183]],"header":{"lines":[1,14],"target":"VeilGardeCLI","what":[6,9],"pin":[10,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":1139,"scopes":[["S","TrainingOptions",null,"",20,20,[20,42],75,null,-1,0,"a"],["f","candidateID",["_"],"",28,28,[28,47],34,null,0,0,"a"],["f","engine",[],"",36,36,[36,43],49,null,0,0,"a"],["f","run",["_"],"",52,52,[52,46],66,[51,51],0,0,"a"],["f","metricsFile",["_"],"",68,68,[68,48],74,null,0,0,"a"],["f","datasetURL",["_"],"",77,77,[77,39],77,null,-1,8,"a"],["S","TrainCommand",null,"",79,79,[79,37],183,null,-1,0,"a"],["S","Plan",null,"",85,85,[85,33],102,null,6,0,"a"],["f","run",[],"",91,91,[91,26],101,null,7,0,"a"],["S","Fusion",null,"",104,104,[104,35],135,null,6,0,"a"],["f","run",[],"",114,114,[114,26],134,null,9,0,"a"],["S","Heads",null,"",137,137,[137,34],153,null,6,0,"a"],["f","run",[],"",142,142,[142,26],152,null,11,0,"a"],["S","Combine",null,"",155,155,[155,36],163,null,6,0,"a"],["f","run",[],"",160,160,[160,26],162,null,13,0,"a"],["S","All",null,"",165,165,[165,32],172,null,6,0,"a"],["f","run",[],"",169,169,[169,26],171,null,15,0,"a"],["S","Run",null,"",174,174,[174,32],182,null,6,0,"a"],["f","run",[],"",179,179,[179,26],181,null,17,0,"a"]],"old":"","new":"//\n//  Train.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde train`: every model VeilGarde ships, trained into a candidate bundle at\n//        <work area>/candidates/<id>/ that `veilgarde route --bundle` runs. `plan` prints what a\n//        recipe would do without doing it; `fusion`, `heads` and `combiner` train one model; `all`\n//        trains the shipped preset and `run` a recipe.toml.\n//  PIN:  The parent bundle is the shipped one unless --parent names another (a candidate, or\n//        <work area>/live). The store defaults to <work area>/store/shards; --store names\n//        another (any store in the same shard format reads as is). Train in release:\n//        VEILGARDE_CONFIG=release scripts/cli.sh train …\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct TrainingOptions: ParsableArguments {\n    @OptionGroup var workArea: WorkAreaOptions\n    @Option(help: \"The bundle the candidate starts from (default: the shipped bundle; `live` for <work area>/live).\") var parent: String?\n    @Option(help: \"The feature store directory (default: <work area>/store/shards).\") var store: String?\n    @Option(help: \"The candidate's id, its folder under <work area>/candidates (default: <what>-<date>-<time>).\") var id: String?\n    @Flag(help: \"Replace a candidate with the same id.\") var replace = false\n    @Flag(help: \"Print the plan and stop.\") var plan = false\n\n    func candidateID(_ what: String) -> String {\n        if let id { return id }\n        let f = DateFormatter()\n        f.locale = Locale(identifier: \"en_US_POSIX\")\n        f.dateFormat = \"yyyyMMdd-HHmmss\"\n        return \"\\(what)-\\(f.string(from: Date()))\"\n    }\n\n    func engine() throws -> TrainingEngine {\n        let area = try workArea.resolve()\n        let parentURL: URL\n        switch parent {\n        case nil: parentURL = ShippedBundle.directory\n        case \"live\"?: parentURL = area.root.appendingPathComponent(\"live\", isDirectory: true)\n        case let path?: parentURL = URL(fileURLWithPath: (path as NSString).expandingTildeInPath, isDirectory: true)\n        }\n        let storeURL = store.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true) }\n        ShippedBundle.registerWeightFolders(workArea: area)\n        let engine = TrainingEngine(area: area, parent: parentURL, store: storeURL) { event in if let line = event.line { note(line) } }\n        engine.replace = replace\n        return engine\n    }\n\n    /// Plans, prints the plan (to stdout with --plan, else to stderr) and trains unless --plan.\n    func run(_ recipe: TrainingRecipe) throws {\n        let engine = try self.engine()\n        let plan = try engine.plan(recipe)\n        if self.plan {\n            print(plan.summary)\n            if !plan.refusals.isEmpty { throw VeilGardeFailure.usage(\"the recipe is refused:\\n  \" + plan.refusals.joined(separator: \"\\n  \")) }\n            return\n        }\n        note(plan.summary)\n        let outcome = try engine.train(recipe)\n        print(\"candidate \\(outcome.candidate.id): \\(outcome.candidate.root.path)\")\n        print(String(format: \"  %d artifacts, trained in %.1fs\", outcome.candidate.manifest.artifacts.count, outcome.seconds))\n        for model in recipe.ordered.map(\\.name) { print(\"  \\(model): \\(outcome.candidate.root.path)/\\(metricsFile(model))\") }\n        print(\"run it:  veilgarde route <image> --bundle \\(outcome.candidate.root.path)\")\n    }\n\n    func metricsFile(_ model: String) -> String {\n        switch model {\n        case \"fusion-head\": return \"fusion/metrics.json\"\n        case \"combiner\": return \"combiner/metrics.json\"\n        default: return \"heads/\\(model.dropFirst(\"head:\".count))/metrics.json\"\n        }\n    }\n}\n\nfunc datasetURL(_ path: String) -> URL { URL(fileURLWithPath: (path as NSString).expandingTildeInPath) }\n\nstruct TrainCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"train\", abstract: \"Train VeilGarde's models into a candidate bundle: the fusion head, the heads, the combiner.\",\n        discussion: \"Train in release (VEILGARDE_CONFIG=release scripts/cli.sh train …). A candidate is a full bundle: run it with `veilgarde route <image> --bundle <candidate>`.\",\n        subcommands: [Plan.self, Fusion.self, Heads.self, Combine.self, All.self, Run.self])\n\n    struct Plan: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"plan\", abstract: \"Print what a recipe would train and why, without training (no writes).\")\n        @Option(help: \"A recipe.toml.\") var recipe: String?\n        @Flag(help: \"The shipped preset.\") var preset = false\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                let r: TrainingRecipe\n                if let recipe { r = try RecipeFile.load(datasetURL(recipe)) } else if preset {\n                    r = TrainingRecipe.shipped(id: options.candidateID(\"shipped\"))\n                } else { throw VeilGardeFailure.usage(\"name a --recipe file or ask for the --preset\") }\n                let plan = try options.engine().plan(r)\n                print(plan.summary)\n                if !plan.refusals.isEmpty { throw VeilGardeFailure.usage(\"the recipe is refused:\\n  \" + plan.refusals.joined(separator: \"\\n  \")) }\n            }\n        }\n    }\n\n    struct Fusion: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"fusion\", abstract: \"Train the fusion head on the store: a warm start on the parent's (the flywheel's way) or from scratch.\")\n        @Option(help: \"warm or scratch.\") var mode: String = \"warm\"\n        @Option(help: \"Trees to add (warm) or to grow (scratch).\") var trees: Int?\n        @Option(help: \"The learning rate.\") var eta: Double?\n        @Option(name: .customLong(\"new-generator-weight\"), help: \"The weight on new-generator rows.\") var newGeneratorWeight: Double = 1.0\n        @Option(help: \"The row's columns: dino_fusion,cap (393) or dino_fusion,dino_norm,cap (777).\") var columns: String?\n        @Option(help: \"The trees' depth (default 5).\") var depth: Int?\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                var f = FusionHead().newGeneratorWeight(newGeneratorWeight)\n                if let columns {\n                    guard let layout = FusionLayout(rawValue: columns.replacingOccurrences(of: \" \", with: \"\")) else {\n                        throw VeilGardeFailure.usage(\"--columns is one of \\(FusionLayout.allCases.map(\\.rawValue).joined(separator: \" or \")), not \\(columns)\")\n                    }\n                    f = f.columns(layout)\n                }\n                if let depth {\n                    guard (1...12).contains(depth) else { throw VeilGardeFailure.usage(\"--depth is 1 to 12, not \\(depth)\") }\n                    f = f.depth(depth)\n                }\n                switch mode {\n                case \"warm\": f = f.warmStart(add: trees ?? 80, eta: eta ?? 0.03)\n                case \"scratch\": f = f.scratch(trees: trees ?? 500, eta: eta ?? 0.04)\n                default: throw VeilGardeFailure.usage(\"--mode is warm or scratch, not \\(mode)\")\n                }\n                try options.run(TrainingRecipe(id: options.candidateID(\"fusion\")) { f })\n            }\n        }\n    }\n\n    struct Heads: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"heads\", abstract: \"Train specialist heads on the store's dino_norm column (each head's recipe, admission measured).\")\n        @Option(help: \"Comma-separated kinds (default: art,blur,human).\") var kinds: String = HeadKind.flywheelCategories.map(\\.rawValue).joined(separator: \",\")\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                let parsed = try kinds.split(separator: \",\").map { name -> HeadKind in\n                    guard let kind = HeadKind(rawValue: String(name)) else {\n                        throw VeilGardeFailure.usage(\"unknown head \\(name); heads are \\(HeadKind.allCases.map(\\.rawValue).joined(separator: \", \"))\")\n                    }\n                    return kind\n                }\n                try options.run(TrainingRecipe(id: options.candidateID(\"heads\")) { for kind in parsed { DinoHead(kind) } })\n            }\n        }\n    }\n\n    struct Combine: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"combiner\", abstract: \"Fit the stack combiner on the store's capture-absent rows under the parent's base and heads.\")\n        @Option(name: .customLong(\"reals-weight\"), help: \"The weight on real rows.\") var realsWeight: Double = 3\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded { try options.run(TrainingRecipe(id: options.candidateID(\"combiner\")) { Combiner().realsWeight(realsWeight) }) }\n        }\n    }\n\n    struct All: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"all\", abstract: \"Train the shipped preset: every model VeilGarde ships that the store reproduces.\")\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded { try options.run(TrainingRecipe.shipped(id: options.candidateID(\"shipped\"))) }\n        }\n    }\n\n    struct Run: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"run\", abstract: \"Train a recipe.toml.\")\n        @Argument(help: \"The recipe file.\") var recipe: String\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded { try options.run(try RecipeFile.load(datasetURL(recipe))) }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Watermark.swift","status":"added","lang":"swift","hunks":[[1,0,1,151]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,10],"pin":[11,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1158,"scopes":[["S","WatermarkCommand",null,"",18,18,[18,41],151,null,-1,0,"a"],["f","signature",["_"],"static",24,24,[24,71],31,null,0,0,"a"],["S","Sign",null,"",33,33,[33,33],45,null,0,0,"a"],["f","run",[],"",38,38,[38,26],44,null,2,0,"a"],["S","Match",null,"",47,47,[47,34],63,null,0,0,"a"],["f","run",[],"",54,54,[54,26],62,null,4,0,"a"],["S","Verify",null,"",65,65,[65,35],77,null,0,0,"a"],["f","run",[],"",70,70,[70,26],76,null,6,0,"a"],["S","Accept",null,"",79,79,[79,35],117,null,0,0,"a"],["f","run",[],"",88,88,[88,26],116,null,8,0,"a"],["S","Invariance",null,"",119,119,[119,39],150,null,0,0,"a"],["f","run",[],"",127,127,[127,26],149,null,10,0,"a"]],"old":"","new":"//\n//  Watermark.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde watermark`: a crop-robust signature read off an image's warp fragility\n//        pattern. `sign` prints it (vw1 text, or JSON); `match` finds where an image (a crop, a\n//        re-encode) sits on a signature; `verify` is match with the verdict as the exit code;\n//        `accept` runs v1's acceptance on final_mixed and evaluates its kill criterion;\n//        `invariance` signs a set of images and, against a baseline, fails on any change.\n//  PIN:  Native resolution, one MLX workload. `accept` and `invariance` write only their reports.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct WatermarkCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"watermark\", abstract: \"Sign an image by its warp fragility pattern, and find a crop or a re-encode of it again.\",\n        discussion: \"v1 is a design under measurement: run `watermark accept` before relying on it.\",\n        subcommands: [Sign.self, Match.self, Verify.self, Accept.self, Invariance.self])\n\n    static func signature(_ text: String) throws -> WatermarkSignature {\n        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)\n        if trimmed.hasPrefix(\"vw1:\") { return try WatermarkSignature(compact: trimmed) }\n        let url = datasetURL(trimmed)\n        let body = try String(contentsOf: url, encoding: .utf8).trimmingCharacters(in: .whitespacesAndNewlines)\n        if body.hasPrefix(\"vw1:\") { return try WatermarkSignature(compact: body) }\n        return try JSONDecoder().decode(WatermarkSignature.self, from: Data(body.utf8))\n    }\n\n    struct Sign: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"sign\", abstract: \"Print an image's watermark signature (vw1 text, or JSON with --json).\")\n        @Argument(help: \"The image.\") var image: String\n        @Flag(help: \"JSON instead of vw1 text.\") var json = false\n\n        func run() throws {\n            guarded {\n                let sig = try Watermark.sign(try loadImage(image))\n                if json { try emitJSON(try JSONCoding.prettyEncoder().encode(sig), to: \"-\") } else { print(sig.compact) }\n                note(\"\\(sig.rows)×\\(sig.cols) tiles, \\(sig.codes.count) sections, \\(sig.measuredBits) bits, cid \\(sig.cid.prefix(16))\")\n            }\n        }\n    }\n\n    struct Match: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"match\", abstract: \"Find where an image sits on a signature: offset, phase, score and its z-score.\")\n        @Argument(help: \"The image (a crop or a re-encode of a signed one).\") var image: String\n        @Argument(help: \"The signature: vw1 text, or a file holding vw1 text or JSON.\") var signature: String\n        @Option(help: \"Grid phases in pixels, comma-separated.\") var phases: String = \"0,8,16,24\"\n        @Flag(help: \"JSON instead of text.\") var json = false\n\n        func run() throws {\n            guarded {\n                let p = phases.split(separator: \",\").compactMap { Int($0.trimmingCharacters(in: .whitespaces)) }\n                let r = try Watermark.match(try loadImage(image), against: try WatermarkCommand.signature(signature), options: MatchOptions(phases: p))\n                if json { try emitJSON(try JSONCoding.prettyEncoder().encode(r), to: \"-\"); return }\n                print(String(format: \"%@: score %.4f over %d bits (z %.1f); offset (%d, %d) tiles at phase (%d, %d) px, the image's origin at (%d, %d) on the signed image\",\n                             r.matched ? \"match\" : \"no match\", r.score, r.bitsCompared, r.zScore, r.offsetX, r.offsetY, r.phaseX, r.phaseY, r.pixelX, r.pixelY))\n            }\n        }\n    }\n\n    struct Verify: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Exit 0 when the image matches the signature, 1 when it does not.\")\n        @Argument(help: \"The image.\") var image: String\n        @Argument(help: \"The signature: vw1 text, or a file holding vw1 text or JSON.\") var signature: String\n\n        func run() throws {\n            guarded {\n                let r = try Watermark.match(try loadImage(image), against: try WatermarkCommand.signature(signature))\n                print(String(format: \"%@ (score %.4f, %d bits, z %.1f)\", r.matched ? \"match\" : \"no match\", r.score, r.bitsCompared, r.zScore))\n                if !r.matched { throw ExitCode(1) }\n            }\n        }\n    }\n\n    struct Accept: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"accept\", abstract: \"v1's acceptance run on a seeded final_mixed sample: crops, JPEG, false matches, the kill criterion.\")\n        @Option(help: \"Images to sample (half real, half generated).\") var n: Int = 200\n        @Option(help: \"final_mixed's folder (manifest.csv) or a dataset.jsonl (default: final_mixed under VEILGARDE_DATASETS, else the work area's datasets/).\") var dataset: String?\n        @Option(help: \"The sample's and the crops' seed.\") var seed: UInt64 = 0\n        @Option(help: \"Grid phases in pixels, comma-separated.\") var phases: String = \"0,8,16,24\"\n        @Option(help: \"Write the report JSON here.\") var out: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                _ = try workArea.resolve()\n                guard let dataset = dataset.map(datasetURL) ?? WorkArea.datasets().map({ $0.appendingPathComponent(\"final_mixed\") }) else {\n                    throw VeilGardeFailure.usage(\"no dataset: pass --dataset or set VEILGARDE_DATASETS\")\n                }\n                let sample = AcceptanceSample.sample(try AcceptanceSample.dataset(dataset), perLabel: max(1, n / 2), seed: seed)\n                var settings = AcceptanceSettings()\n                settings.seed = seed\n                settings.phases = phases.split(separator: \",\").compactMap { Int($0.trimmingCharacters(in: .whitespaces)) }\n                note(\"accept: \\(sample.count) images from \\(dataset.path)\")\n                // Each image's row as it is measured, so a long run that stops keeps what it measured.\n                let rowsURL = out.map { datasetURL($0).deletingPathExtension().appendingPathExtension(\"rows.jsonl\") }\n                let rows = try rowsURL.map { try JSONLWriter(url: $0, truncate: true) }\n                let report = try WatermarkAcceptance.run(sample.map { ($0.url, $0.label) }, settings: settings, note: note,\n                                                         measured: { try? rows?.append($0) })\n                let s = report.summary\n                print(String(format: \"images %d; self-match %.1f%%; crop matched with its offset %.1f%%; JPEG q75 median score %.3f\", s.images, s.selfMatchRate * 100,\n                             s.cropMatchRate * 100, s.jpegMedianScore))\n                print(String(format: \"cross-image false matches at 0.75: %.1f%% (median cross score %.3f)\", s.crossFalseMatchRate * 100, s.crossMedianScore))\n                if let t = s.operatingThreshold { print(String(format: \"operating point: threshold %.2f, crop recall %.1f%%, false matches %.1f%%\", t, (s.operatingRecall ?? 0) * 100, (s.operatingFalseMatchRate ?? 0) * 100)) }\n                print(\"bit balance (E, S, SE, NE): \" + s.bitBalance.map { String(format: \"%.3f\", $0) }.joined(separator: \", \"))\n                for (k, v) in s.resizedMatchRate.sorted(by: { $0.key > $1.key }) {\n                    print(String(format: \"resized %@× (every %d-th image): matched %.1f%%\", k, settings.resizeEvery, v * 100))\n                }\n                print(s.killed ? \"v1 KILLED: \" + s.reasons.joined(separator: \"; \") : \"v1 passes its acceptance\")\n                if let out { try JSONCoding.write(report, to: datasetURL(out)); note(\"report: \\(out)\") }\n            }\n        }\n    }\n\n    struct Invariance: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"invariance\", abstract: \"Sign images exactly as `sign` does and record each signature; with --baseline, exit 1 on any difference.\",\n            discussion: \"A gate for changes near the warp residual: take the baseline before the change and re-run after every build. One MLX workload.\")\n        @Option(help: \"A folder (searched recursively), a text file of image paths, or an image; repeatable.\") var images: [String]\n        @Option(help: \"A previous invariance report to compare against.\") var baseline: String?\n        @Option(help: \"Write the report here.\") var out: String\n\n        func run() throws {\n            guarded {\n                let urls = try images.flatMap(imageInputs)\n                guard !urls.isEmpty else { throw VeilGardeFailure.usage(\"no images found in \\(images.joined(separator: \", \"))\") }\n                note(\"invariance: \\(urls.count) images\")\n                let started = Date()\n                let report = WatermarkInvariance.measure(urls, note: note)\n                try JSONCoding.write(report, to: datasetURL(out))\n                print(String(format: \"signed %d images (%d skipped) in %.1fs\", report.images.count, report.skipped.count, Date().timeIntervalSince(started)))\n                for s in report.skipped { print(\"skipped \\(s)\") }\n                note(\"report: \\(out)\")\n                guard let baseline else { return }\n                let reference = try JSONCoding.read(InvarianceReport.self, from: datasetURL(baseline))\n                let differences = WatermarkInvariance.compare(baseline: reference, current: report)\n                if differences.isEmpty {\n                    print(\"invariant: all \\(reference.images.count) signatures equal the baseline\")\n                    return\n                }\n                for d in differences { print(\"DIFFERENT \\(d.path) \\(d.field): \\(d.baseline) → \\(d.current)\") }\n                print(\"\\(differences.count) differences from the baseline\")\n                throw ExitCode(1)\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Weights.swift","status":"added","lang":"swift","hunks":[[1,0,1,136]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1170,"scopes":[["S","WeightsCommand",null,"",18,18,[18,39],136,null,-1,0,"a"],["S","List",null,"",22,22,[22,33],36,null,0,0,"a"],["f","run",[],"",26,26,[26,26],35,null,1,0,"a"],["S","Verify",null,"",38,38,[38,35],56,null,0,0,"a"],["f","run",[],"",42,42,[42,26],55,null,3,0,"a"],["S","ImportDINOv2",null,"",58,58,[58,41],87,null,0,0,"a"],["f","run",[],"",69,69,[69,26],86,null,5,0,"a"],["S","ExportXXSmall",null,"",89,89,[89,42],107,null,0,0,"a"],["f","run",[],"",96,96,[96,26],106,null,7,0,"a"],["f","describe",["_"],"static",109,109,[109,70],120,null,0,0,"a"],["S","ImportCLIP",null,"",122,122,[122,39],135,null,0,0,"a"],["f","run",[],"",128,128,[128,26],134,null,10,0,"a"]],"old":"","new":"//\n//  Weights.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde weights`: where the neural weights are and whether they are the ones the bundle\n//        was built with. `list` shows each weight's search result; `verify` re-hashes them against\n//        the shipped manifest and exits 1 on a mismatch or a missing file. `import-dinov2` builds\n//        the three DINOv2 files from Hugging Face's\n//        checkpoint (downloading it when no file is named), `export-xxsmall` quantizes an xsmall\n//        file, and `import-clip` converts CLIP's vision tower from a safetensors checkpoint.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct WeightsCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"weights\", abstract: \"List and verify the DINOv2 and CLIP weights.\",\n                                                    subcommands: [List.self, Verify.self, ImportDINOv2.self, ExportXXSmall.self, ImportCLIP.self])\n\n    struct List: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"list\", abstract: \"Show where each weight file is found, in search order.\")\n        @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first.\") var weightsDir: String?\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n                print(\"search path: \" + WeightLocator.shared.searchPath().map(\\.path).joined(separator: \" → \"))\n                for file in WeightFile.allCases {\n                    print(\"  \" + file.rawValue.padding(toLength: 34, withPad: \" \", startingAt: 0) + (WeightLocator.shared.url(file)?.path ?? \"not found\"))\n                }\n            }\n        }\n    }\n\n    struct Verify: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Re-hash each weight against the hash the shipped manifest records.\")\n        @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first.\") var weightsDir: String?\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n                var failures = 0\n                for expected in ShippedBundle.manifest.weights {\n                    guard let url = WeightLocator.shared.url(named: expected.file) else { print(\"missing  \\(expected.file)\"); failures += 1; continue }\n                    let sha = try ArtifactHashCache.shared.sha256(url)\n                    print(\"\\(sha == expected.sha256 ? \"ok      \" : \"MISMATCH\") \\(expected.file)  \\(sha.prefix(12))  \\(url.path)\")\n                    if sha != expected.sha256 { failures += 1 }\n                }\n                if failures > 0 { throw ArgumentParser.ExitCode(FailureCode.doctor.rawValue) }\n            }\n        }\n    }\n\n    struct ImportDINOv2: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"import-dinov2\", abstract: \"Build dinov2_small, _xsmall and _xxsmall from Hugging Face's facebook/dinov2-small checkpoint.\",\n            discussion: \"With no --from, the checkpoint is downloaded into <work area>/hf. A file already in the output folder is compared tensor by tensor and kept; the new one goes to <out>/imported unless --replace.\")\n        @Option(help: \"The checkpoint: a model.safetensors, or a folder holding one.\") var from: String?\n        @Option(help: \"The output folder (default: <work area>/weights).\") var out: String?\n        @Option(help: \"small, xsmall, xxsmall or all.\") var variant: String = \"all\"\n        @Flag(help: \"Replace files already in the output folder.\") var replace = false\n        @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first for the files to compare against.\") var weightsDir: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                ShippedBundle.registerWeightFolders(workArea: area)\n                if let weightsDir { WeightLocator.shared.setOverride(datasetURL(weightsDir)) }\n                let variants: [DinoVariant]\n                if variant == \"all\" { variants = DinoVariant.allCases } else {\n                    guard let v = DinoVariant(rawValue: variant) else { throw VeilGardeFailure.usage(\"--variant is small, xsmall, xxsmall or all, not \\(variant)\") }\n                    variants = [v]\n                }\n                let checkpoint = try Dinov2Import.checkpoint(from.map(datasetURL), hfBase: area.root.appendingPathComponent(\"hf\", isDirectory: true))\n                let output = out.map(datasetURL) ?? area.weights\n                let report = try Dinov2Import.importWeights(checkpoint: checkpoint, variants: variants, output: output, replace: replace,\n                                                            reference: { WeightLocator.shared.url($0.weightFile) }, note: note)\n                print(\"checkpoint \\(report.checkpoint) (sha256 \\(report.checkpointSHA256.prefix(12)))\")\n                for file in report.files { print(WeightsCommand.describe(file)) }\n            }\n        }\n    }\n\n    struct ExportXXSmall: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"export-xxsmall\", abstract: \"Quantize an xsmall DINOv2 file into xxsmall (8-bit Linear weights in groups of 64), as the runtime quantizes it.\")\n        @Option(help: \"The xsmall file (default: the one the weight search finds).\") var from: String?\n        @Option(help: \"The output file (default: <work area>/weights/imported/dinov2_small_xxsmall.safetensors).\") var out: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                ShippedBundle.registerWeightFolders(workArea: area)\n                guard let source = from.map(datasetURL) ?? WeightLocator.shared.url(.dinov2XSmall) else {\n                    throw VeilGardeFailure.missing(\"no xsmall DINOv2 file found; name one with --from\")\n                }\n                let output = out.map(datasetURL) ?? area.weights.appendingPathComponent(\"imported/\\(WeightFile.dinov2XXSmall.rawValue)\")\n                print(WeightsCommand.describe(try Dinov2Import.exportXXSmall(fromXSmall: source, to: output, reference: WeightLocator.shared.url(.dinov2XXSmall))))\n            }\n        }\n    }\n\n    static func describe(_ file: Dinov2Import.ImportedFile) -> String {\n        var line = \"\\(file.variant): \\(file.tensors) tensors → \\(file.path) (sha256 \\(file.sha256.prefix(12)))\"\n        if file.keptExisting { line += \"; the existing file was kept\" }\n        if let c = file.comparison {\n            if c.sameFile { line += \"\\n  byte-identical to \\(c.reference)\" } else {\n                line += \"\\n  against \\(c.reference): \\(c.identicalBytes) of \\(c.tensors) tensors byte-identical, max |Δ| \\(String(format: \"%.3g\", c.maxAbsDifference))\"\n                    + (c.worst.map { \" (\\($0))\" } ?? \"\")\n                for problem in c.problems.prefix(6) { line += \"\\n  \\(problem)\" }\n            }\n        }\n        return line\n    }\n\n    struct ImportCLIP: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"import-clip\", abstract: \"Convert CLIP ViT-B/32's vision tower from a Hugging Face safetensors file into the work area's weights.\")\n        @Option(help: \"The checkpoint: a CLIPModel model.safetensors (or a vision-only one).\") var from: String\n        @Option(help: \"The output file (default: <work area>/weights/clip_vit_b32_vision.safetensors).\") var out: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let output = try out.map(datasetURL) ?? workArea.resolve().root.appendingPathComponent(\"weights/\\(WeightFile.clipVision.rawValue)\")\n                let report = try CLIPImport.convert(from: datasetURL(from), to: output)\n                print(\"\\(report.tensors) tensors → \\(report.output) (sha256 \\(report.sha256.prefix(12)))\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Options.swift","status":"added","lang":"swift","hunks":[[1,0,1,132]],"header":{"lines":[1,9],"target":"VeilGardeCLI","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1182,"scopes":[["S","WorkAreaOptions",null,"",16,16,[16,42],27,null,-1,0,"a"],["f","resolve",[],"",20,20,[20,38],26,null,0,0,"a"],["f","guarded",["_"],"",30,30,[30,40],42,[29,29],-1,0,"a"],["f","guardedAsync",["_"],"",45,45,[45,57],57,[44,44],-1,0,"a"],["f","note",["_"],"",60,60,[60,26],60,[59,59],-1,8,"a"],["f","loadImage",["_"],"",63,63,[63,49],65,[62,62],-1,0,"a"],["f","imageInputs",["_"],"",69,69,[69,50],86,[67,68],-1,0,"a"],["f","emitJSON",["_","to"],"",89,89,[89,59],96,[88,88],-1,0,"a"],["f","timed",["_"],"",99,99,[99,62],103,[98,98],-1,0,"a"],["S","RouteOptions",null,"",106,106,[106,39],126,[105,105],-1,0,"a"],["f","config",[],"",116,116,[116,44],125,null,9,0,"a"],["f","parseHint",["_"],"",128,128,[128,58],132,null,-1,0,"a"]],"old":"","new":"//\n//  Options.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The options every command shares: the work area (--work-area, else VEILGARDE_WORK_AREA,\n//        else refused), the failure mapping to sysexits so scripts can branch, and the stderr note\n//        every progress line goes through.\n//\n\nimport ArgumentParser\nimport CoreGraphics\nimport Foundation\nimport VeilGarde\n\nstruct WorkAreaOptions: ParsableArguments {\n    @Option(name: .customLong(\"work-area\"), help: \"Where VeilGarde's data lives (default: VEILGARDE_WORK_AREA).\")\n    var workAreaPath: String?\n\n    func resolve() throws -> WorkArea {\n        if let workAreaPath { return WorkArea(root: URL(fileURLWithPath: (workAreaPath as NSString).expandingTildeInPath, isDirectory: true)) }\n        guard let area = WorkArea.resolve() else {\n            throw VeilGardeFailure.configuration(\"no work area\", hint: \"set VEILGARDE_WORK_AREA or pass --work-area: VeilGarde writes no data it was not told where to put\")\n        }\n        return area\n    }\n}\n\n/// Runs a command body, printing a VeilGardeFailure and exiting with its code; other errors are internal.\nfunc guarded(_ body: () throws -> Void) {\n    do {\n        try body()\n    } catch let failure as VeilGardeFailure {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(failure.description)\\n\".utf8))\n        exit(failure.code.rawValue)\n    } catch let exit as ArgumentParser.ExitCode {\n        Foundation.exit(exit.rawValue)\n    } catch {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(error)\\n\".utf8))\n        exit(FailureCode.internalError.rawValue)\n    }\n}\n\n/// The async form of `guarded`.\nfunc guardedAsync(_ body: () async throws -> Void) async {\n    do {\n        try await body()\n    } catch let failure as VeilGardeFailure {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(failure.description)\\n\".utf8))\n        exit(failure.code.rawValue)\n    } catch let exit as ArgumentParser.ExitCode {\n        Foundation.exit(exit.rawValue)\n    } catch {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(error)\\n\".utf8))\n        exit(FailureCode.internalError.rawValue)\n    }\n}\n\n/// A progress line, to stderr.\nfunc note(_ text: String) { FileHandle.standardError.write(Data((text + \"\\n\").utf8)) }\n\n/// Reads an image the way the detector sees it (EXIF orientation applied).\nfunc loadImage(_ path: String) throws -> CGImage {\n    try ImageDecoding.cgImage(contentsOf: URL(fileURLWithPath: (path as NSString).expandingTildeInPath))\n}\n\n/// The images an argument names: a text file of paths (one per line, `#` comments), a folder\n/// (searched recursively, sorted by path, exFAT sidecars skipped), or one image.\nfunc imageInputs(_ input: String) throws -> [URL] {\n    let url = datasetURL(input)\n    if url.pathExtension == \"txt\" {\n        let text = try String(contentsOf: url, encoding: .utf8)\n        return text.split(separator: \"\\n\").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty && !$0.hasPrefix(\"#\") }.map(datasetURL)\n    }\n    var isDirectory: ObjCBool = false\n    guard FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory) else { throw VeilGardeFailure.missing(\"no image or folder at \\(url.path)\") }\n    guard isDirectory.boolValue else { return [url] }\n    var out: [URL] = []\n    let walker = FileManager.default.enumerator(at: url, includingPropertiesForKeys: [.isRegularFileKey], options: [.skipsHiddenFiles])\n    while let next = walker?.nextObject() as? URL {\n        let name = next.lastPathComponent\n        guard !name.hasPrefix(\"._\"), ShardExtractor.imageExtensions.contains(next.pathExtension.lowercased()) else { continue }\n        out.append(next)\n    }\n    return out.sorted { $0.path < $1.path }\n}\n\n/// Writes JSON to stdout with a trailing newline (`--json -`), or to a file.\nfunc emitJSON(_ data: Data, to destination: String) throws {\n    if destination == \"-\" {\n        FileHandle.standardOutput.write(data)\n        FileHandle.standardOutput.write(Data(\"\\n\".utf8))\n    } else {\n        try data.write(to: URL(fileURLWithPath: (destination as NSString).expandingTildeInPath))\n    }\n}\n\n/// Wall seconds of `body`.\nfunc timed<T>(_ body: () throws -> T) rethrows -> (T, Double) {\n    let t0 = DispatchTime.now()\n    let value = try body()\n    return (value, Double(DispatchTime.now().uptimeNanoseconds - t0.uptimeNanoseconds) / 1e9)\n}\n\n/// The detector's flags, shared by `route`, `batch` and `research census`.\nstruct RouteOptions: ParsableArguments {\n    @Option(name: .customLong(\"semantic-profile\"), help: \"control, semantic_diagnostic_only or semantic_removed.\")\n    var semanticProfile: String = SemanticResponsibility.control.rawValue\n    @Option(help: \"DINOv2 weights: small (F32), xsmall (F16) or xxsmall (int8).\")\n    var dino: String = DinoVariant.small.rawValue\n    @Option(help: \"A bundle directory to detect with instead of the shipped one (the flywheel's live/ or a candidate).\")\n    var bundle: String?\n    @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first for the DINOv2 and CLIP weights.\")\n    var weightsDir: String?\n\n    func config() throws -> InferenceConfig {\n        ShippedBundle.registerWeightFolders()\n        if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n        let detectorBundle = try bundle.map { try DetectorBundle.load(URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true)) } ?? .shipped\n        guard let profile = SemanticResponsibility(rawValue: semanticProfile) else {\n            throw VeilGardeFailure.usage(\"--semantic-profile must be control, semantic_diagnostic_only or semantic_removed, not \\(semanticProfile)\")\n        }\n        guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino must be small, xsmall or xxsmall, not \\(dino)\") }\n        return InferenceConfig(bundle: detectorBundle, dinoVariant: variant, semanticResponsibility: profile)\n    }\n}\n\nfunc parseHint(_ raw: String?) throws -> DetectionDomain? {\n    guard let raw else { return nil }\n    guard let hint = DetectionDomain(rawValue: raw) else { throw VeilGardeFailure.usage(\"--hint must be camera or screenshot, not \\(raw)\") }\n    return hint\n}\n"},{"path":"Sources/VeilGardeCLI/VeilGardeCommand.swift","status":"added","lang":"swift","hunks":[[1,0,1,32]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1194,"scopes":[["S","VeilGardeCommand",null,"",18,19,[19,46],32,null,-1,0,"a"],["f","run",[],"",29,29,[29,28],31,null,0,0,"a"]],"old":"","new":"//\n//  VeilGardeCommand.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The `veilgarde` root command. Bare `veilgarde` prints help; the subcommands detect\n//        (route, batch), extract and train (features, train), run the flywheel, measure the\n//        detector part by part (research), sign and match watermarks, manage weights and bundles,\n//        and check the DINOv2 and CLIP towers against their references (parity).\n//  PIN:  Results go to stdout and progress to stderr, so `veilgarde route x.jpg --json | jq`\n//        stays clean. A VeilGardeFailure exits with its sysexits code (Options.swift).\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\n@main\nstruct VeilGardeCommand: AsyncParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"veilgarde\",\n        abstract: \"VeilGarde, the AI-generated-image detector: a fusion head over DINOv2 and the capture signature, the specialist stack on it, the flywheel that grows them, and a crop-robust watermark read off a warp residual.\",\n        discussion: \"Start with `veilgarde doctor`. Every command writes its result to stdout; add --json where offered.\",\n        version: VeilGardeVersion.string,\n        subcommands: [DoctorCommand.self, RouteCommand.self, BatchCommand.self, FeaturesCommand.self,\n                      TrainCommand.self, FlywheelCommand.self, ResearchCommand.self, WatermarkCommand.self, WeightsCommand.self, BundleCommand.self, ParityCommand.self]\n    )\n\n    func run() async throws {\n        print(VeilGardeCommand.helpMessage())\n    }\n}\n"}]};
